import heapq


def merge_logs(*streams):
    iterators = [iter(stream) for stream in streams]
    heap = []                                   # (timestamp, stream number, entry): the next entry of each stream
    for number, iterator in enumerate(iterators):
        entry = next(iterator, None)
        if entry is not None:
            heap.append((entry[0], number, entry))
    heapq.heapify(heap)
    while heap:
        _, number, entry = heap[0]
        yield entry
        following = next(iterators[number], None)       # read the next entry only when the caller wants more
        if following is None:
            heapq.heappop(heap)
        else:
            heapq.heapreplace(heap, (following[0], number, following))
